import 'package:flutter/material.dart';
import 'package:flutter_animate/flutter_animate.dart';
class FeatureScreen extends StatelessWidget { const FeatureScreen({required this.title, required this.message, super.key}); final String title; final String message; @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: Text(title)), body: Center(child: Padding(padding: const EdgeInsets.all(24), child: Column(mainAxisSize: MainAxisSize.min, children: [Icon(Icons.auto_awesome, size: 48, color: Theme.of(context).colorScheme.primary), const SizedBox(height: 16), Text(title, style: Theme.of(context).textTheme.headlineMedium), const SizedBox(height: 8), Text(message, textAlign: TextAlign.center)]).animate().fadeIn().slideY(begin: .08)))); }
